pub fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // Problem guarantees: list is non-empty and 1 <= k < n (so n >= 2).
    let n = list.len();
    debug_assert!(n >= 2);
    debug_assert!(1 <= k && k < n);

    let idx = k - 1; // convert 1-based k to 0-based index
    let mut new_list = Vec::with_capacity(n - 1);

    // Copy prefix: elements before idx
    new_list.extend_from_slice(&list[..idx]);
    // Copy suffix: elements after idx
    new_list.extend_from_slice(&list[idx + 1..]);

    new_list
}